function c_csrf():void{echo '<input type="hidden" name="csrf" value="'.e(csrf_token()).'">';}
function c_hidden(string $name,string|int $value):void{echo '<input type="hidden" name="'.e($name).'" value="'.e((string)$value).'">';}
function c_select(string $name,string $label,array $rows,?int $selected=null):void{echo '<label for="'.e($name).'">'.e($label).'</label><select id="'.e($name).'" name="'.e($name).'"><option value="">None</option>';foreach($rows as $row){echo '<option value="'.(int)$row['id'].'"'.($selected===(int)$row['id']?' selected':'').'>'.e($row['name']??$row['title']??('Image #'.$row['id'])).'</option>';}echo '</select>';}
